SELECT id, practice_script->>'version' AS version, md5(practice_script::text) AS huella FROM public.nodes WHERE id IN ('1.2','1.5','1.6','2.1','2.10') ORDER BY id;
SELECT id, md5(concat_ws('|', paso, tipo, canal, procedencia, resumen, cita_cerebro, severidad_default)) AS huella FROM public.reglas WHERE id IN ('blocks.air','blocks.ataque_en_disculpa','blocks.discute_bloqueo','blocks.dos_no_seguidos','blocks.mala_experiencia_al_llegar','monologo','opening.curiosidad_abierta','opening.energia_verbal','opening.especificidad','opening.estructura','opening.halago_falso','opening.ice_breaker','opening.pide_permiso','opening.pitch_prematuro','opening.pregunta_cerrada','relationship.cpr','relationship.familiaridad_excesiva','relationship.forms','relationship.interes_fingido','story.cierra_con_afirmacion','story.kill','story.kill_curriculum','story.kiss','story.nunca_sale','story.pregunta_despues','story.quien_eres_por_que','story.sale_sin_regresar') ORDER BY id;
SELECT max(version) AS version_cerebro, count(*) AS secciones, md5(string_agg(body, '#' ORDER BY order_index)) AS huella_cerebro FROM public.doctrina WHERE is_active;
